def gen(rng):
    SETS = [[1], [1, 4, 9], [2, 8, 18, 50], [1, 2, 3, 4, 6, 12], list(range(1, 101)), [2, 3, 5, 6, 10, 15, 30],
            [1, 2, 4, 8, 16, 32, 64], [36, 25, 49, 2, 3, 7, 14, 21, 42]]

    def build(n, rng, maxdepth, mode):
        # parent[i] < i for i >= 1, depth counted in nodes (root has depth 1)
        depth = [1] * n
        par = [-1] * n
        for i in range(1, n):
            if mode == 'path':
                p = i - 1
            elif mode == 'star':
                p = 0
            elif mode == 'deep':
                p = i - 1 if rng.random() < 0.7 else rng.randint(max(0, i - 50), i - 1)
            else:
                p = rng.randint(0, i - 1)
            tries = 0
            while depth[p] + 1 > maxdepth:
                p = rng.randint(0, i - 1)
                tries += 1
                if tries > 50:
                    p = 0
            par[i] = p
            depth[i] = depth[p] + 1
        return par

    def fmt(n, vals, par):
        # relabel non-root nodes randomly, shuffle edge order and orientation
        perm = list(range(1, n))
        rng.shuffle(perm)
        lab = [0] + perm
        newvals = [0] * n
        for i in range(n):
            newvals[lab[i]] = vals[i]
        edges = []
        for i in range(1, n):
            a, b = lab[par[i]], lab[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        lines = [str(n), ' '.join(map(str, newvals))]
        lines += [f"{a} {b}" for a, b in edges]
        return '\n'.join(lines)

    def make(n, mode, maxdepth, vs=None):
        par = build(n, rng, maxdepth, mode)
        pool = vs if vs is not None else rng.choice(SETS)
        vals = [rng.choice(pool) for _ in range(n)]
        return fmt(n, vals, par)

    tests = ['1\n1', '1\n2', '1\n100', '2\n2 8\n0 1', '3\n2 3 6\n0 1\n1 2', '3\n1 1 1\n0 1\n0 2',
             '3\n6 6 1\n0 1\n0 2', '4\n2 2 2 2\n0 1\n1 2\n2 3']
    for n in (2, 3, 4, 5, 6, 8, 10, 12, 14):
        for mode in ('rand', 'path', 'star', 'deep'):
            if rng.random() < 0.6:
                tests.append(make(n, mode, 5000))
    for _ in range(6):
        tests.append(make(rng.randint(5, 14), 'rand', 5000, rng.choice(SETS)))
    N = 100000
    tests.append(make(N, 'rand', 5000, [1]))
    tests.append(make(N, 'rand', 5000, list(range(1, 101))))
    tests.append(make(N, 'deep', 5000, [1, 4, 9, 2, 8, 18]))
    tests.append(make(N, 'deep', 5000, [2, 3, 6, 5, 10, 15, 30]))
    tests.append(make(N, 'star', 5000, [1, 2, 3, 4]))
    return tests
